import { useEffect, useId, useRef, useState } from "react";
import { ChevronRight } from "lucide-react";
import { Button } from "./button";

// KMP-C27 (specs/KMP-C27-next-week-notice.md). A neutral notice in the page flow: not a dialog, not a live region.
// Dismiss calls onDismiss and removes the notice; focus moves to the next focusable element after it, never to the page top.
// "Hidden once next week was viewed" is the consumer's: it stops rendering the component. No timer ever removes it.

export const NEXT_WEEK_TITLE = "Next week is planned.";

export type NextWeekNoticeProps = {
  /** For example "9 to 15 November", formatted by the consumer. */
  dateRange: string;
  /** Next week on the Week screen. */
  href: string;
  onDismiss?: () => void;
  /** Link text, default "See next week". */
  linkLabel?: string;
  dismissLabel?: string;
};

const FOCUSABLE = 'a[href], button, input, select, textarea, [tabindex]:not([tabindex="-1"])';

export function NextWeekNotice({ dateRange, href, onDismiss, linkLabel = "See next week", dismissLabel = "Dismiss" }: NextWeekNoticeProps) {
  const dateId = useId();
  const root = useRef<HTMLDivElement>(null);
  const next = useRef<HTMLElement | null>(null);
  const [gone, setGone] = useState(false);

  useEffect(() => {
    if (gone) next.current?.focus();
  }, [gone]);

  if (gone) return null;

  const dismiss = () => {
    const box = root.current!;
    next.current =
      [...document.querySelectorAll<HTMLElement>(FOCUSABLE)].find(
        (el) => !box.contains(el) && !!(box.compareDocumentPosition(el) & Node.DOCUMENT_POSITION_FOLLOWING),
      ) ?? null;
    onDismiss?.();
    setGone(true);
  };

  return (
    <div ref={root} className="flex flex-col gap-stack-sm rounded-control border-bw-default border-border-strong bg-surface-raised p-inset-md font-body leading-normal">
      <div>
        <p className="text-ui-body font-medium text-text">{NEXT_WEEK_TITLE}</p>
        <p id={dateId} className="text-ui-floor font-regular text-text-muted">
          {dateRange}
        </p>
      </div>
      <div className="flex flex-wrap items-center gap-gap-md">
        <a
          href={href}
          aria-describedby={dateId}
          className="inline-flex min-h-control items-center gap-gap-sm rounded-control px-inset-md text-ui-reading font-medium text-primary-text underline hover:text-text active:text-text focus-visible:outline focus-visible:outline-ring focus-visible:outline-offset-ring focus-visible:outline-focus-ring"
        >
          {linkLabel}
          <ChevronRight aria-hidden="true" className="size-icon-sm shrink-0" />
        </a>
        <Button variant="quiet" onClick={dismiss}>
          {dismissLabel}
        </Button>
      </div>
    </div>
  );
}
